package dev.valence.license;

import dev.valence.ValenceClient;
import java.net.InetAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpRequest.BodyPublishers;
import java.net.http.HttpResponse.BodyHandlers;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.time.Duration;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.fabricmc.loader.api.FabricLoader;

@Environment(EnvType.CLIENT)
public final class License {
   public static final String SERVER_URL = "";
   private static final String SALT = "vl-5a14694f4fea1ac0c66e89db";
   private static final String SECRET = "b30c6a028ab5f9f6e80eb85e0b869914";
   private static final String HASHES = "";
   private static final int HASH_LEN = 24;
   private static final Set<String> VALID = new HashSet<>();
   private static volatile boolean active;
   private static boolean loaded;

   private License() {
   }

   public static boolean active() {
      return true;
   }

   public static String normalize(String code) {
      StringBuilder sb = new StringBuilder();

      for (char ch : code.toUpperCase(Locale.ROOT).toCharArray()) {
         if (ch >= 'A' && ch <= 'Z' || ch >= '0' && ch <= '9') {
            sb.append(ch);
         }
      }

      return sb.toString();
   }

   private static String codeHash(String code) {
      return sha("vl-5a14694f4fea1ac0c66e89db" + code).substring(0, 24);
   }

   public static boolean looksValid(String code) {
      String c = normalize(code);
      return c.length() == 8 && VALID.contains(codeHash(c));
   }

   public static CompletableFuture<License.Result> redeem(String raw) {
      String code = normalize(raw);
      if (code.length() != 8 || !VALID.contains(codeHash(code))) {
         return CompletableFuture.completedFuture(License.Result.INVALID);
      } else {
         return "".isBlank()
            ? CompletableFuture.completedFuture(activate(code) ? License.Result.OK : License.Result.ERROR)
            : CompletableFuture.supplyAsync(
               () -> {
                  try {
                     HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8L)).build();
                     String body = "{\"code\":\"" + code + "\",\"machine\":\"" + machine() + "\"}";
                     HttpRequest req = HttpRequest.newBuilder(URI.create("".replaceAll("/+$", "") + "/redeem"))
                        .timeout(Duration.ofSeconds(10L))
                        .header("Content-Type", "application/json")
                        .POST(BodyPublishers.ofString(body))
                        .build();
                     HttpResponse<String> res = http.send(req, BodyHandlers.ofString());
                     String b = res.body() == null ? "" : res.body();
                     if (res.statusCode() == 200 && b.contains("\"ok\":true")) {
                        return activate(code) ? License.Result.OK : License.Result.ERROR;
                     } else if (b.contains("used")) {
                        return License.Result.USED;
                     } else {
                        return b.contains("invalid") ? License.Result.INVALID : License.Result.ERROR;
                     }
                  } catch (Exception e) {
                     ValenceClient.LOGGER.warn("Valence license server not reachable: {}", e.toString());
                     return License.Result.OFFLINE;
                  }
               }
            );
      }
   }

   private static boolean activate(String code) {
      String h = codeHash(code);
      String m = machine();
      String line = h + "|" + m + "|" + sign(h, m);
      boolean saved = false;

      for (Path p : files()) {
         try {
            Files.createDirectories(p.getParent());
            Files.writeString(p, line, StandardCharsets.UTF_8);
            saved = true;
         } catch (Exception e) {
            ValenceClient.LOGGER.warn("Valence: could not save the license to {}", p);
         }
      }

      active = saved;
      loaded = true;
      return saved;
   }

   private static boolean readActivation() {
      String m = machine();

      for (Path p : files()) {
         try {
            if (Files.isRegularFile(p)) {
               String[] parts = Files.readString(p, StandardCharsets.UTF_8).trim().split("\\|");
               if (parts.length == 3 && VALID.contains(parts[0]) && parts[1].equals(m) && parts[2].equals(sign(parts[0], m))) {
                  for (Path q : files()) {
                     if (!Files.isRegularFile(q)) {
                        try {
                           Files.createDirectories(q.getParent());
                           Files.writeString(q, String.join("|", parts), StandardCharsets.UTF_8);
                        } catch (Exception var11) {
                        }
                     }
                  }

                  return true;
               }
            }
         } catch (Exception var12) {
         }
      }

      return false;
   }

   private static Path[] files() {
      Path home = Path.of(System.getProperty("user.home", "."));

      Path cfg;
      try {
         cfg = FabricLoader.getInstance().getConfigDir();
      } catch (Throwable t) {
         cfg = Path.of("config");
      }

      return new Path[]{home.resolve(".valence").resolve("license.dat"), cfg.resolve("valence-license.dat")};
   }

   static String machine() {
      String host = System.getenv("COMPUTERNAME");
      if (host == null || host.isBlank()) {
         host = System.getenv("HOSTNAME");
      }

      if (host == null || host.isBlank()) {
         try {
            host = InetAddress.getLocalHost().getHostName();
         } catch (Exception e) {
            host = "pc";
         }
      }

      String id = System.getProperty("user.name", "") + "@" + host.toLowerCase(Locale.ROOT) + "/" + System.getProperty("os.name", "");
      return sha("m:" + id).substring(0, 20);
   }

   private static String sign(String hash, String machine) {
      return sha("b30c6a028ab5f9f6e80eb85e0b869914:" + hash + ":" + machine).substring(0, 32);
   }

   private static String sha(String s) {
      try {
         byte[] d = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
         StringBuilder sb = new StringBuilder();

         for (byte b : d) {
            sb.append(String.format("%02x", b));
         }

         return sb.toString();
      } catch (Exception e) {
         throw new IllegalStateException(e);
      }
   }

   static {
      for (int i = 0;
         i + 24
            <= ""
               .length();
         i += 24
      ) {
         VALID.add(
            ""
               .substring(i, i + 24)
         );
      }
   }

   @Environment(EnvType.CLIENT)
   public enum Result {
      OK,
      INVALID,
      USED,
      OFFLINE,
      ERROR;
   }
}
